INSERT INTO property_intelligence.societies (id, name, city, address, noc_approved, noc_summary, details_source_url, record_type)
SELECT gen_random_uuid(), v.name, 'Lahore', v.addr, v.noc, v.summ, 'https://lda.gop.pk/approved-schemes', 'FACT' FROM v
WHERE NOT EXISTS (SELECT 1 FROM property_intelligence.societies x WHERE x.city = 'Lahore' AND lower(regexp_replace(x.name,'[^a-zA-Z0-9]','','g')) = lower(regexp_replace(v.name,'[^a-zA-Z0-9]','','g')))
RETURNING id
)
INSERT INTO property_intelligence.candidate_societies (id, name, regulator, city, status, record_type)
SELECT gen_random_uuid(), v.name, 'LDA', 'Lahore', 'ONBOARDED', 'FACT' FROM v
WHERE NOT EXISTS (SELECT 1 FROM property_intelligence.candidate_societies c WHERE c.regulator = 'LDA' AND lower(regexp_replace(c.name,'[^a-zA-Z0-9]','','g')) = lower(regexp_replace(v.name,'[^a-zA-Z0-9]','','g')));

